diff --git a/calendar/base/modules/utils/calItipUtils.sys.mjs b/calendar/base/modules/utils/calItipUtils.sys.mjs
index c9b4eeb9a03..6a7406a547a 100644
--- a/calendar/base/modules/utils/calItipUtils.sys.mjs
+++ b/calendar/base/modules/utils/calItipUtils.sys.mjs
@@ -1338,7 +1338,10 @@ export var itip = {
   getInvitedAttendee(aItem, aCalendar) {
     const id = aItem.getProperty("X-MOZ-INVITED-ATTENDEE");
     if (id) {
-      return aItem.getAttendeeById(id);
+      const attendee = aItem.getAttendeeById(id);
+      if (attendee) {
+        return attendee;
+      }
     }
     if (!aCalendar) {
       aCalendar = aItem.calendar;
